export const API_KEY_ERROR = "API Key not found. Please ensure process.env.API_KEY is set.";

import React, { useState, useEffect, useRef } from 'react';
import { CallState, VoiceName, Scenario } from './types';
import { LiveClient } from './services/liveClient';
import Visualizer from './components/Visualizer';
import { SCENARIOS, API_KEY_ERROR } from './constants';

// Assuming API Key is injected by the environment as per instructions
const API_KEY = process.env.API_KEY || '';

const App: React.FC = () => {
  const [callState, setCallState] = useState<CallState>(CallState.IDLE);
  const [selectedScenario, setSelectedScenario] = useState<Scenario>(SCENARIOS[0]);
  const [volume, setVolume] = useState(0);
  const [duration, setDuration] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const liveClientRef = useRef<LiveClient | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    if (callState === CallState.ACTIVE) {
      timerRef.current = window.setInterval(() => {
        setDuration(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
      if (callState === CallState.IDLE) {
        setDuration(0);
      }
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [callState]);

  const startCall = async () => {
    if (!API_KEY) {
      setErrorMsg(API_KEY_ERROR);
      setCallState(CallState.ERROR);
      return;
    }

    setCallState(CallState.CONNECTING);
    setErrorMsg(null);

    const client = new LiveClient({
      apiKey: API_KEY,
      voiceName: VoiceName.Puck,
      systemInstruction: selectedScenario.systemInstruction,
      onOpen: () => {
        setCallState(CallState.ACTIVE);
      },
      onClose: () => {
        setCallState(CallState.ENDED);
      },
      onError: (err) => {
        console.error(err);
        setErrorMsg(err.message);
        setCallState(CallState.ERROR);
      },
      onVolumeChange: (vol) => {
        setVolume(vol);
      }
    });

    liveClientRef.current = client;
    await client.connect();
  };

  const endCall = async () => {
    if (liveClientRef.current) {
      await liveClientRef.current.disconnect();
      liveClientRef.current = null;
    }
    setCallState(CallState.ENDED);
  };

  const reset = () => {
    setCallState(CallState.IDLE);
    setVolume(0);
    setDuration(0);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-[#131314] text-gray-200">

      {/* Header/Status Bar Look */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-center text-[#e3e3e3] opacity-80 z-20">
        <div className="text-sm font-medium flex items-center gap-2">
            <span className="material-icons-round text-base">signal_cellular_alt</span>
            <span>Gemini 5G</span>
        </div>
        <div className="text-sm font-semibold tracking-wider">ENGLISH TUTOR</div>
        <div className="text-sm flex items-center gap-2">
             <span>100%</span>
             <span className="material-icons-round text-base">battery_full</span>
        </div>
      </div>

      <main className="w-full max-w-md bg-[#1e1e20] rounded-3xl shadow-2xl overflow-hidden border border-[#444746] relative h-[800px] max-h-[90vh] flex flex-col">

        {/* Decorative Background Elements */}
        <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-[#004a77]/20 to-transparent pointer-events-none"></div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col items-center justify-center p-8 relative z-10">

          {/* IDLE STATE: Scenario Selection */}
          {callState === CallState.IDLE && (
            <div className="w-full space-y-8 animate-fade-in">
              <div className="text-center space-y-2">
                <h1 className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">
                    Who do you want to call?
                </h1>
                <p className="text-gray-400">Select a scenario to practice</p>
              </div>

              <div className="grid grid-cols-2 gap-3">
                {SCENARIOS.map((scenario) => (
                    <button
                        key={scenario.id}
                        onClick={() => setSelectedScenario(scenario)}
                        className={`p-4 rounded-2xl border transition-all duration-200 text-left hover:scale-[1.02] flex flex-col gap-2
                            ${selectedScenario.id === scenario.id 
                                ? 'bg-[#004a77]/30 border-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.3)]' 
                                : 'bg-[#2a2a2c] border-transparent hover:bg-[#323235]'
                            }`}
                    >
                        <span className="text-3xl filter drop-shadow-md">{scenario.emoji}</span>
                        <span className={`font-medium ${selectedScenario.id === scenario.id ? 'text-blue-100' : 'text-gray-300'}`}>
                            {scenario.title}
                        </span>
                    </button>
                ))}
              </div>

              <div className="pt-8 flex justify-center">
                 <button 
                    onClick={startCall}
                    className="group relative flex items-center justify-center w-20 h-20 bg-green-500 rounded-full hover:bg-green-400 transition-all shadow-lg hover:shadow-green-500/40 hover:scale-110 active:scale-95"
                 >
                    <span className="material-icons-round text-4xl text-white">call</span>
                    <span className="absolute -inset-1 rounded-full border border-green-500 opacity-50 animate-pulse-slow"></span>
                 </button>
              </div>
              <p className="text-center text-xs text-gray-500 mt-4">Tap to start conversation</p>
            </div>
          )}

          {/* CONNECTING STATE */}
          {callState === CallState.CONNECTING && (
             <div className="text-center space-y-8 animate-pulse">
                <div className="w-32 h-32 rounded-full bg-gray-700 mx-auto flex items-center justify-center">
                    <span className="text-6xl">{selectedScenario.emoji}</span>
                </div>
                <div>
                    <h2 className="text-2xl font-semibold text-white">{selectedScenario.title}</h2>
                    <p className="text-blue-300 mt-2">Calling...</p>
                </div>
             </div>
          )}

          {/* ACTIVE CALL STATE */}
          {callState === CallState.ACTIVE && (
            <div className="flex flex-col items-center justify-between h-full w-full py-8">
                <div className="text-center space-y-2">
                    <h2 className="text-2xl font-bold text-white">{selectedScenario.title}</h2>
                    <p className="text-gray-400 font-mono tracking-widest text-sm">{formatTime(duration)}</p>
                </div>

                <div className="flex-1 flex items-center justify-center w-full">
                    <Visualizer volume={volume} isConnected={true} />
                </div>

                <div className="w-full flex justify-center items-center gap-8 mt-8">
                     <button className="p-4 rounded-full bg-[#2a2a2c] text-white hover:bg-[#323235] transition-colors">
                        <span className="material-icons-round text-2xl">mic</span>
                     </button>
                     <button 
                        onClick={endCall}
                        className="w-16 h-16 rounded-full bg-red-500 hover:bg-red-600 flex items-center justify-center shadow-lg shadow-red-500/30 transition-transform hover:scale-105 active:scale-95"
                    >
                        <span className="material-icons-round text-3xl text-white">call_end</span>
                     </button>
                     <button className="p-4 rounded-full bg-[#2a2a2c] text-white hover:bg-[#323235] transition-colors">
                        <span className="material-icons-round text-2xl">volume_up</span>
                     </button>
                </div>
            </div>
          )}

           {/* ENDED STATE */}
           {callState === CallState.ENDED && (
              <div className="text-center space-y-6">
                <div className="w-24 h-24 rounded-full bg-gray-700 mx-auto flex items-center justify-center grayscale">
                    <span className="text-4xl">{selectedScenario.emoji}</span>
                </div>
                <div>
                    <h2 className="text-xl font-semibold">Call Ended</h2>
                    <p className="text-gray-400 mt-1">Duration: {formatTime(duration)}</p>
                </div>

                <div className="flex flex-col gap-3 w-64 mx-auto pt-4">
                    <button 
                        onClick={startCall}
                        className="w-full py-3 bg-green-600 hover:bg-green-500 rounded-xl text-white font-medium transition-colors flex items-center justify-center gap-2"
                    >
                         <span className="material-icons-round">replay</span>
                         Call Again
                    </button>
                    <button 
                        onClick={reset}
                        className="w-full py-3 bg-[#2a2a2c] hover:bg-[#323235] rounded-xl text-white font-medium transition-colors"
                    >
                        Back to Menu
                    </button>
                </div>
              </div>
           )}

            {/* ERROR STATE */}
            {callState === CallState.ERROR && (
              <div className="text-center p-6 space-y-4">
                 <span className="material-icons-round text-red-500 text-5xl">error_outline</span>
                 <h2 className="text-xl font-bold text-red-400">Connection Error</h2>
                 <p className="text-gray-300 text-sm">{errorMsg || "Something went wrong."}</p>
                 <button 
                    onClick={reset}
                    className="px-6 py-2 bg-gray-700 rounded-full hover:bg-gray-600 transition-colors mt-4"
                >
                    Try Again
                </button>
              </div>
           )}

        </div>
      </main>

      <footer className="mt-8 text-xs text-gray-500 flex flex-col items-center gap-2">
         <p>Powered by Gemini 2.5 Flash Native Audio</p>
         <div className="flex gap-4">
             <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span>
             <span className="w-1.5 h-1.5 rounded-full bg-purple-500"></span>
             <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
         </div>
      </footer>
    </div>
  );
};

export default App;

