          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: this.config.voiceName } },
          },
          systemInstruction: this.config.systemInstruction,
        },
      });

      this.session = sessionPromise;

    } catch (error: any) {
      console.error('Connection failed:', error);
      this.config.onError(error);
    }
  }

  setMute(muted: boolean) {
    if (this.mediaStream) {
        this.mediaStream.getAudioTracks().forEach(track => {
            track.enabled = !muted;
        });
    }
  }

  private startAudioInputStream(sessionPromise: Promise<any>) {
    if (!this.inputAudioContext || !this.mediaStream) return;

    this.inputSource = this.inputAudioContext.createMediaStreamSource(this.mediaStream);
    this.scriptProcessor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
      if (!this.isConnected) return;

      const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
      const pcmBlob = createPcmBlob(inputData);

      sessionPromise.then((session) => {
        session.sendRealtimeInput({ media: pcmBlob });
      });
    };

    this.inputSource.connect(this.scriptProcessor);
    this.scriptProcessor.connect(this.inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    if (!this.outputAudioContext || !this.analyzer) return;

    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;

    if (base64Audio) {
        // Ensure context is running (mobile browsers sometimes suspend it)
        if(this.outputAudioContext.state === 'suspended') {
            await this.outputAudioContext.resume();
        }

        const audioData = base64ToUint8Array(base64Audio);
        this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);

        const audioBuffer = await decodeAudioData(
            audioData,
            this.outputAudioContext,
            24000,
            1
        );

        const source = this.outputAudioContext.createBufferSource();
        source.buffer = audioBuffer;

        // Connect to analyzer for visuals, then to destination
        source.connect(this.analyzer);
        // We already connected analyzer to destination in constructor, but let's be explicit with gain
        const gainNode = this.outputAudioContext.createGain();
        source.connect(gainNode);
        gainNode.connect(this.outputAudioContext.destination);

        source.start(this.nextStartTime);
        this.nextStartTime += audioBuffer.duration;

        source.addEventListener('ended', () => {
            this.sources.delete(source);
        });
        this.sources.add(source);

        // Simple volume estimation for visualizer based on buffer data
        const channelData = audioBuffer.getChannelData(0);
        let sum = 0;
        // Sample a few points for efficiency
        for(let i=0; i<channelData.length; i+=100) {
             sum += Math.abs(channelData[i]);
        }
        const avg = sum / (channelData.length / 100);
        this.config.onVolumeChange(Math.min(avg * 5, 1)); // Scale up a bit
    }

    const interrupted = message.serverContent?.interrupted;
    if (interrupted) {
      console.log('Model interrupted');
      this.sources.forEach((source) => {
        source.stop();
        this.sources.delete(source);
      });
      this.nextStartTime = 0;
    }
  }

  async disconnect() {
    this.isConnected = false;

    if (this.session) {
      // There is no explicit close method on the promise wrapper in SDK doc, 
      // but usually we just stop sending and close context.
      // If the SDK object returned by resolved promise has close(), use it.
      const s = await this.session;
      if(s && typeof s.close === 'function') {
          s.close();
      }
    }

    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach(track => track.stop());
    }

    if (this.inputSource) this.inputSource.disconnect();
    if (this.scriptProcessor) this.scriptProcessor.disconnect();

    if (this.inputAudioContext) await this.inputAudioContext.close();
    if (this.outputAudioContext) await this.outputAudioContext.close();

    this.sources.forEach(s => s.stop());
    this.sources.clear();
  }
}

import React from 'react';

interface VisualizerProps {
  volume: number; // 0 to 1
  isConnected: boolean;
}

const Visualizer: React.FC<VisualizerProps> = ({ volume, isConnected }) => {
  if (!isConnected) {
    return (
      <div className="flex items-center justify-center space-x-2 h-32">
        <div className="flex gap-1">
            <div className="w-2 h-2 rounded-full bg-blue-500 animate-bounce" style={{ animationDelay: '0s' }}></div>
            <div className="w-2 h-2 rounded-full bg-blue-500 animate-bounce" style={{ animationDelay: '0.2s' }}></div>
            <div className="w-2 h-2 rounded-full bg-blue-500 animate-bounce" style={{ animationDelay: '0.4s' }}></div>
        </div>
      </div>
    );
  }

  // Generate a symmetrical waveform pattern
  // Center bars are taller, edges are shorter
  const bars = 7;
  const renderBars = () => {
    return Array.from({ length: bars }).map((_, i) => {
        // Calculate distance from center (0 to 3)
        const center = Math.floor(bars / 2);
        const dist = Math.abs(i - center);

        // Scale volume influence based on position (center reacts most)
        // Base height 24px, max height 96px
        const scale = 1 - (dist * 0.2); 
        const height = 24 + (volume * 100 * scale);

        return (
            <div 
                key={i}
                className="w-3 mx-1 bg-blue-500 rounded-full transition-all duration-75 ease-out"
                style={{ 
                    height: `${Math.min(height, 120)}px`,
                    opacity: 0.5 + (volume * 0.5) // slight opacity pulse
                }}
            ></div>
        );
    });
  };

  return (
    <div className="w-full h-48 flex items-center justify-center">
        <div className="flex items-center justify-center h-full">
            {renderBars()}
        </div>
    </div>
  );
};

export default Visualizer;

import React, { useState, useEffect, useRef } from 'react';
import { CallState, VoiceName, Scenario } from './types';
import { LiveClient } from './services/liveClient';
import Visualizer from './components/Visualizer';
import { SCENARIOS, API_KEY_ERROR } from './constants';

// Assuming API Key is injected by the environment as per instructions
const API_KEY = process.env.API_KEY || '';

const App: React.FC = () => {
  const [callState, setCallState] = useState<CallState>(CallState.IDLE);
  const [selectedScenario, setSelectedScenario] = useState<Scenario>(SCENARIOS[0]);
  const [volume, setVolume] = useState(0);
  const [duration, setDuration] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isMuted, setIsMuted] = useState(false);

  const liveClientRef = useRef<LiveClient | null>(null);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    if (callState === CallState.ACTIVE) {
      timerRef.current = window.setInterval(() => {
        setDuration(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
      if (callState === CallState.IDLE) {
        setDuration(0);
        setIsMuted(false);
      }
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [callState]);

  const startCall = async () => {
    if (!API_KEY) {
      setErrorMsg(API_KEY_ERROR);
      setCallState(CallState.ERROR);
      return;
    }

    setCallState(CallState.CONNECTING);
    setErrorMsg(null);

    const client = new LiveClient({
      apiKey: API_KEY,
      voiceName: VoiceName.Puck,
      systemInstruction: selectedScenario.systemInstruction,
      onOpen: () => {
        setCallState(CallState.ACTIVE);
      },
      onClose: () => {
        setCallState(CallState.ENDED);
      },
      onError: (err) => {
        console.error(err);
        setErrorMsg(err.message);
        setCallState(CallState.ERROR);
      },
      onVolumeChange: (vol) => {
        setVolume(vol);
      }
    });

    liveClientRef.current = client;
    await client.connect();
  };

  const endCall = async () => {
    if (liveClientRef.current) {
      await liveClientRef.current.disconnect();
      liveClientRef.current = null;
    }
    setCallState(CallState.ENDED);
  };

  const toggleMute = () => {
    const nextState = !isMuted;
    setIsMuted(nextState);
    if (liveClientRef.current) {
        liveClientRef.current.setMute(nextState);
    }
  };

  const reset = () => {
    setCallState(CallState.IDLE);
    setVolume(0);
    setDuration(0);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#131314] text-[#e3e3e3] font-sans flex flex-col">

      {/* Header */}
      <header className="px-8 py-6 flex items-center justify-between border-b border-[#444746]">
        <div className="flex items-center gap-3">
             <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
                <span className="material-icons-round text-white text-lg">school</span>
             </div>
             <h1 className="text-lg font-semibold tracking-wide">English Tutor <span className="text-gray-500 font-normal mx-2">|</span> <span className="text-blue-400 font-medium">Gemini 2.5</span></h1>
        </div>
        <div className="hidden md:flex items-center gap-6 text-sm text-gray-400">
            <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-green-500"></span>
                <span>System Operational</span>
            </div>
            <span>v1.0.0</span>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 md:p-8">

        {/* Main Interface Container */}
        <div className="w-full max-w-6xl mx-auto bg-[#1e1e20] rounded-2xl border border-[#444746] overflow-hidden shadow-xl min-h-[600px] flex flex-col md:flex-row relative">

          {/* Decorative grid background */}
          <div className="absolute inset-0 opacity-5 pointer-events-none" 
               style={{ backgroundImage: 'radial-gradient(circle, #ffffff 1px, transparent 1px)', backgroundSize: '24px 24px' }}>
          </div>

          {/* Sidebar / Scenario Selector (Desktop) */}
          <div className={`md:w-1/3 border-r border-[#444746] bg-[#2a2a2c]/50 backdrop-blur-sm flex flex-col z-10 transition-transform duration-300
               ${callState === CallState.IDLE ? 'translate-x-0' : 'hidden md:flex'}
          `}>
             <div className="p-6 border-b border-[#444746]">
                <h2 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Select Scenario</h2>
             </div>
             <div className="overflow-y-auto flex-1 p-4 space-y-3">
                {SCENARIOS.map((scenario) => (
                    <button
                        key={scenario.id}
                        disabled={callState !== CallState.IDLE}
                        onClick={() => setSelectedScenario(scenario)}
                        className={`w-full p-4 rounded-xl text-left border transition-all duration-200 group relative overflow-hidden
                            ${selectedScenario.id === scenario.id 
                                ? 'bg-[#004a77]/30 border-blue-500/50' 
                                : 'bg-[#1e1e20] border-transparent hover:border-gray-600 hover:bg-[#323235]'
                            }
                            ${callState !== CallState.IDLE && selectedScenario.id !== scenario.id ? 'opacity-50' : ''}
                        `}
                    >
                        <div className="flex items-center gap-4 relative z-10">
                            <span className="text-2xl bg-[#131314] w-12 h-12 flex items-center justify-center rounded-lg">{scenario.emoji}</span>
                            <div>
                                <h3 className={`font-medium ${selectedScenario.id === scenario.id ? 'text-blue-100' : 'text-gray-200'}`}>{scenario.title}</h3>
                                <p className="text-xs text-gray-500 mt-1 truncate">Interactive Conversation</p>
                            </div>
                        </div>
                        {selectedScenario.id === scenario.id && (
                             <div className="absolute right-4 top-1/2 -translate-y-1/2">
                                <span className="material-icons-round text-blue-400">check_circle</span>
                             </div>
                        )}
                    </button>
                ))}
             </div>
          </div>

          {/* Main Stage */}
          <div className="flex-1 flex flex-col relative z-10">

            {/* Top Bar of Stage */}
            <div className="h-16 border-b border-[#444746] flex items-center justify-between px-6 bg-[#1e1e20]">
                <div className="flex items-center gap-3">
                     <span className="text-xl">{selectedScenario.emoji}</span>
                     <span className="font-medium text-lg">{selectedScenario.title}</span>
                </div>
                <div>
                     {callState === CallState.ACTIVE && (
                         <span className="px-3 py-1 bg-red-500/10 text-red-400 rounded-full text-xs font-medium border border-red-500/20 flex items-center gap-2">
                             <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse"></span>
                             LIVE
                         </span>
                     )}
                </div>
            </div>

            {/* Stage Content */}
            <div className="flex-1 flex items-center justify-center bg-[#131314]/50 relative overflow-hidden">

                {callState === CallState.IDLE && (
                    <div className="text-center space-y-6 max-w-md px-6">
                        <div className="w-24 h-24 mx-auto bg-[#1e1e20] rounded-full flex items-center justify-center border border-[#444746] shadow-2xl">
                            <span className="material-icons-round text-5xl text-gray-500">record_voice_over</span>
                        </div>
                        <div>
                             <h2 className="text-2xl font-semibold mb-2">Ready to Practice?</h2>
                             <p className="text-gray-400">Select a scenario from the sidebar and start the call to begin your English conversation session.</p>
                        </div>
                        <button 
                            onClick={startCall}
                            className="px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white font-medium rounded-full transition-all shadow-lg shadow-blue-600/20 hover:shadow-blue-600/40 hover:-translate-y-0.5"
                        >
                            Start Conversation
                        </button>
                    </div>
                )}

                {(callState === CallState.CONNECTING || callState === CallState.ACTIVE) && (
                     <div className="w-full h-full flex flex-col items-center justify-center p-8">
                         <div className="flex-1 w-full flex items-center justify-center">
                            <Visualizer volume={volume} isConnected={true} />
                         </div>
                         <div className="mt-8 text-3xl font-mono text-gray-400 font-light tracking-widest">
                             {formatTime(duration)}
                         </div>
                     </div>
                )}

                 {callState === CallState.ENDED && (
                    <div className="text-center space-y-6 animate-fade-in">
                        <span className="material-icons-round text-6xl text-gray-600">check_circle_outline</span>
                        <h2 className="text-2xl font-semibold">Session Complete</h2>
                        <div className="flex gap-4 justify-center">
                            <button 
                                onClick={reset}
                                className="px-6 py-2 border border-[#444746] hover:bg-[#323235] rounded-lg transition-colors"
                            >
                                Back to Menu
                            </button>
                            <button 
                                onClick={startCall}
                                className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition-colors"
                            >
                                Restart Session
                            </button>
                        </div>
                    </div>
                )}

                {callState === CallState.ERROR && (
                    <div className="text-center space-y-4 text-red-400">
                        <span className="material-icons-round text-5xl">warning</span>
                        <p>{errorMsg || "An error occurred."}</p>
                        <button onClick={reset} className="text-sm underline hover:text-red-300">Try Again</button>
                    </div>
                )}
            </div>

            {/* Bottom Controls Bar */}
            <div className="h-24 border-t border-[#444746] bg-[#1e1e20] flex items-center justify-center gap-6 relative z-20">
                 {callState === CallState.ACTIVE ? (
                     <>
                        <button 
                            onClick={toggleMute}
                            className={`w-14 h-14 rounded-full flex items-center justify-center border transition-all duration-200
                                ${isMuted 
                                    ? 'bg-red-500/10 border-red-500/50 text-red-400' 
                                    : 'bg-[#2a2a2c] border-transparent hover:bg-[#323235] text-white'
                                }
                            `}
                        >
                            <span className="material-icons-round text-2xl">
                                {isMuted ? 'mic_off' : 'mic'}
                            </span>
                        </button>

                        <button 
                            onClick={endCall}
                            className="h-14 px-8 rounded-full bg-red-600 hover:bg-red-500 text-white font-medium shadow-lg shadow-red-600/20 transition-all hover:scale-105 flex items-center gap-2"
                        >
                            <span className="material-icons-round">call_end</span>
                            <span>End Call</span>
                        </button>

                         <button className="w-14 h-14 rounded-full bg-[#2a2a2c] text-gray-400 hover:text-white hover:bg-[#323235] flex items-center justify-center transition-colors">
                            <span className="material-icons-round text-2xl">settings</span>
                        </button>
                     </>
                 ) : (
                     <div className="text-sm text-gray-500 italic">
                         {callState === CallState.IDLE ? "Ready to connect" : callState === CallState.ENDED ? "Session ended" : "Status: " + callState}
                     </div>
                 )}
            </div>
          </div>
        </div>

      </main>
    </div>
  );
};

