import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { createPcmBlob, decodeAudioData, base64ToUint8Array } from '../utils/audioUtils';

interface LiveClientConfig {
  apiKey: string;
  systemInstruction: string;
  voiceName: string;
  onOpen: () => void;
  onClose: () => void;
  onError: (error: Error) => void;
  onVolumeChange: (volume: number) => void;
  onTranscript: (speaker: 'user' | 'model', text: string) => void;
}

export class LiveClient {
  private ai: GoogleGenAI;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private mediaStream: MediaStream | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private session: any = null; // Holds the active session
  private config: LiveClientConfig;
  private isConnected = false;
  private scriptProcessor: ScriptProcessorNode | null = null;
  private inputSource: MediaStreamAudioSourceNode | null = null;
  private analyzer: AnalyserNode | null = null;

  constructor(config: LiveClientConfig) {
    this.config = config;
    this.ai = new GoogleGenAI({ apiKey: config.apiKey });
  }

  async connect() {
    try {
      this.inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      this.outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      // Setup Analyzer for visualizer
      this.analyzer = this.outputAudioContext.createAnalyser();
      this.analyzer.fftSize = 256;
      this.analyzer.connect(this.outputAudioContext.destination);

      this.mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = this.ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            console.log('Live API Connected');
            this.isConnected = true;
            this.config.onOpen();
            this.startAudioInputStream(sessionPromise);
          },
          onmessage: async (message: LiveServerMessage) => {
            await this.handleMessage(message);
          },
          onclose: () => {
            console.log('Live API Closed');
            this.isConnected = false;
            this.config.onClose();
          },
          onerror: (e: any) => {
            console.error('Live API Error', e);
            this.config.onError(new Error(e.message || 'Unknown error'));
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: this.config.voiceName } },
          },
          systemInstruction: this.config.systemInstruction,
          // Enable transcription
          inputAudioTranscription: { model: 'google-provided-model' },
          outputAudioTranscription: { model: 'google-provided-model' },
        },
      });

      this.session = sessionPromise;

    } catch (error: any) {
      console.error('Connection failed:', error);
      this.config.onError(error);
    }
  }

  setMute(muted: boolean) {
    if (this.mediaStream) {
        this.mediaStream.getAudioTracks().forEach(track => {
            track.enabled = !muted;
        });
    }
  }

  private startAudioInputStream(sessionPromise: Promise<any>) {
    if (!this.inputAudioContext || !this.mediaStream) return;

    this.inputSource = this.inputAudioContext.createMediaStreamSource(this.mediaStream);
    this.scriptProcessor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
      if (!this.isConnected) return;

      const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
      const pcmBlob = createPcmBlob(inputData);

      sessionPromise.then((session) => {
        session.sendRealtimeInput({ media: pcmBlob });
      });
    };

    this.inputSource.connect(this.scriptProcessor);
    this.scriptProcessor.connect(this.inputAudioContext.destination);
  }

  private async handleMessage(message: LiveServerMessage) {
    // Handle Transcriptions
    if (message.serverContent?.modelTurn?.parts) {
        for (const part of message.serverContent.modelTurn.parts) {
            if (part.text) {
                this.config.onTranscript('model', part.text);
            }
        }
    }

    if (message.serverContent?.turnComplete && message.serverContent?.interrupted !== true) {
        // sometimes user input comes here if needed, but usually streamed separately
        // Check input transcription
    }

    // Input transcription often comes in separate serverContent updates
    if (message.serverContent?.inputTranscription?.text) {
         // This is a partial or final transcription of user input
         // We might want to debounce this in UI, but here we just emit
         this.config.onTranscript('user', message.serverContent.inputTranscription.text);
    }


    if (!this.outputAudioContext || !this.analyzer) return;

    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;

    if (base64Audio) {
        // Ensure context is running (mobile browsers sometimes suspend it)
        if(this.outputAudioContext.state === 'suspended') {
            await this.outputAudioContext.resume();
        }

        const audioData = base64ToUint8Array(base64Audio);
        this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);

        const audioBuffer = await decodeAudioData(
            audioData,
            this.outputAudioContext,
            24000,
            1
        );

        const source = this.outputAudioContext.createBufferSource();
        source.buffer = audioBuffer;

        // Connect to analyzer for visuals, then to destination
        source.connect(this.analyzer);
        // We already connected analyzer to destination in constructor, but let's be explicit with gain
        const gainNode = this.outputAudioContext.createGain();
        source.connect(gainNode);
        gainNode.connect(this.outputAudioContext.destination);

        source.start(this.nextStartTime);
        this.nextStartTime += audioBuffer.duration;

        source.addEventListener('ended', () => {
            this.sources.delete(source);
        });
        this.sources.add(source);

        // Simple volume estimation for visualizer based on buffer data
        const channelData = audioBuffer.getChannelData(0);
        let sum = 0;
        // Sample a few points for efficiency
        for(let i=0; i<channelData.length; i+=100) {
             sum += Math.abs(channelData[i]);
        }
        const avg = sum / (channelData.length / 100);
        this.config.onVolumeChange(Math.min(avg * 5, 1)); // Scale up a bit
    }

    const interrupted = message.serverContent?.interrupted;
    if (interrupted) {
      console.log('Model interrupted');
      this.sources.forEach((source) => {
        source.stop();
        this.sources.delete(source);
      });
      this.nextStartTime = 0;
    }
  }

  async disconnect() {
    this.isConnected = false;

    if (this.session) {
      const s = await this.session;
      if(s && typeof s.close === 'function') {
          s.close();
      }
    }

    if (this.mediaStream) {
      this.mediaStream.getTracks().forEach(track => track.stop());
    }

    if (this.inputSource) this.inputSource.disconnect();
    if (this.scriptProcessor) this.scriptProcessor.disconnect();

    if (this.inputAudioContext) await this.inputAudioContext.close();
    if (this.outputAudioContext) await this.outputAudioContext.close();

    this.sources.forEach(s => s.stop());
    this.sources.clear();
  }
}

import { GoogleGenAI, Type } from '@google/genai';
import { AnalysisReport, TranscriptItem } from '../types';

export async function generateAnalysisReport(apiKey: string, transcript: TranscriptItem[]): Promise<AnalysisReport> {
  const ai = new GoogleGenAI({ apiKey });

  // Filter out empty transcripts and format
  const conversationText = transcript
    .filter(t => t.text.trim() !== '')
    .map(t => `${t.speaker === 'user' ? 'Student' : 'Tutor'}: ${t.text}`)
    .join('\n');

  const prompt = `
    Analyze the following English learning conversation. 
    The "Student" is an English learner. 
    Identify 3-5 key grammatical errors or unnatural phrasings made by the Student.
    Provide a correction and a brief explanation for each.
    Also provide an overall score out of 100 based on grammar, vocabulary, and fluency (inferred).
    Provide a short motivating summary.

    Conversation:
    ${conversationText}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            corrections: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  original: { type: Type.STRING },
                  correction: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from model");
    return JSON.parse(text) as AnalysisReport;
  } catch (error) {
    console.error("Report generation failed", error);
    // Return a dummy error report if it fails
    return {
        score: 0,
        summary: "Could not generate report due to an error.",
        corrections: []
    };
  }
}

