import React, { useState, useEffect, useRef } from 'react';
import { CallState, VoiceName, Scenario, VoiceConfig, TranscriptItem, AnalysisReport } from './types';
import { LiveClient } from './services/liveClient';
import { generateAnalysisReport } from './services/reportService';
import Visualizer from './components/Visualizer';
import Transcript from './components/Transcript';
import ReportCard from './components/ReportCard';
import { SCENARIOS, VOICES, ACCENTS, API_KEY_ERROR } from './constants';

const API_KEY = process.env.API_KEY || '';

const App: React.FC = () => {
  const [callState, setCallState] = useState<CallState>(CallState.IDLE);
  const [selectedScenario, setSelectedScenario] = useState<Scenario>(SCENARIOS[0]);
  const [selectedVoice, setSelectedVoice] = useState<VoiceConfig>(VOICES[0]); // Default Puck
  const [selectedAccent, setSelectedAccent] = useState(ACCENTS[0]); // Default American
  const [volume, setVolume] = useState(0);
  const [duration, setDuration] = useState(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isMuted, setIsMuted] = useState(false);
  const [transcript, setTranscript] = useState<TranscriptItem[]>([]);
  const [showTranscript, setShowTranscript] = useState(false);
  const [report, setReport] = useState<AnalysisReport | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const liveClientRef = useRef<LiveClient | null>(null);
  const timerRef = useRef<number | null>(null);

  // Timer logic
  useEffect(() => {
    if (callState === CallState.ACTIVE) {
      timerRef.current = window.setInterval(() => {
        setDuration(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
      if (callState === CallState.IDLE) {
        setDuration(0);
        setIsMuted(false);
        setTranscript([]);
        setReport(null);
      }
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [callState]);

  const startCall = async () => {
    if (!API_KEY) {
      setErrorMsg(API_KEY_ERROR);
      setCallState(CallState.ERROR);
      return;
    }

    setCallState(CallState.CONNECTING);
    setErrorMsg(null);
    setTranscript([]);

    // Construct system instruction with accent
    const fullSystemInstruction = `
      ${selectedScenario.systemInstruction} 
      IMPORTANT: ${selectedAccent.instruction}
    `;

    const client = new LiveClient({
      apiKey: API_KEY,
      voiceName: selectedVoice.name,
      systemInstruction: fullSystemInstruction,
      onOpen: () => {
        setCallState(CallState.ACTIVE);
      },
      onClose: () => {
        handleCallEnd();
      },
      onError: (err) => {
        console.error(err);
        setErrorMsg(err.message);
        setCallState(CallState.ERROR);
      },
      onVolumeChange: (vol) => {
        setVolume(vol);
      },
      onTranscript: (speaker, text) => {
        setTranscript(prev => {
           const last = prev[prev.length - 1];
           // If the last item is from the same speaker and < 2 seconds ago, append
           // Otherwise new bubble. Simplified for now: always new or naive check
           // Better: Live API sends fragments. We need to handle updates.
           // For simplicity in this demo: we just append distinct non-empty phrases.
           // A real production app needs sophisticated debouncing/merging of 'user' partials.

           // Simple duplicate check for this demo to avoid flood
           if (last && last.speaker === speaker && last.text === text) return prev;

           return [...prev, {
             id: Date.now().toString() + Math.random(),
             speaker,
             text,
             timestamp: new Date()
           }];
        });
      }
    });

    liveClientRef.current = client;
    await client.connect();
  };

  const endCall = async () => {
    if (liveClientRef.current) {
      await liveClientRef.current.disconnect();
      liveClientRef.current = null;
    }
    // Call state handling moves to handleCallEnd called by onClose callback
  };

  const handleCallEnd = async () => {
    setCallState(CallState.ENDED);
    setIsAnalyzing(true);
    // Generate Report
    if (transcript.length > 0) {
        const r = await generateAnalysisReport(API_KEY, transcript);
        setReport(r);
    } else {
        setReport({
            score: 0,
            summary: "No conversation detected.",
            corrections: []
        });
    }
    setIsAnalyzing(false);
  };

  const toggleMute = () => {
    const nextState = !isMuted;
    setIsMuted(nextState);
    if (liveClientRef.current) {
        liveClientRef.current.setMute(nextState);
    }
  };

  const reset = () => {
    setCallState(CallState.IDLE);
    setVolume(0);
    setDuration(0);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#131314] text-[#e3e3e3] font-sans flex flex-col">

      {/* Header */}
      <header className="px-8 py-6 flex items-center justify-between border-b border-[#444746]">
        <div className="flex items-center gap-3">
             <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center">
                <span className="material-icons-round text-white text-lg">school</span>
             </div>
             <h1 className="text-lg font-semibold tracking-wide">English Tutor <span className="text-gray-500 font-normal mx-2">|</span> <span className="text-blue-400 font-medium">Gemini 2.5</span></h1>
        </div>
        <div className="hidden md:flex items-center gap-6 text-sm text-gray-400">
             {/* Status Indicators */}
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center p-4 md:p-8">

        {/* Main Interface Container */}
        <div className="w-full max-w-6xl mx-auto bg-[#1e1e20] rounded-2xl border border-[#444746] overflow-hidden shadow-xl min-h-[700px] flex flex-col md:flex-row relative">

          {/* Sidebar / Configuration (Desktop) */}
          <div className={`md:w-1/3 border-r border-[#444746] bg-[#2a2a2c]/50 backdrop-blur-sm flex flex-col z-10 transition-transform duration-300
               ${callState === CallState.IDLE ? 'translate-x-0' : 'hidden md:flex'}
          `}>
             <div className="p-6 border-b border-[#444746]">
                <h2 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Setup Session</h2>
             </div>

             <div className="overflow-y-auto flex-1 p-6 space-y-8">

                {/* Voice Selection */}
                <div className="space-y-3">
                    <label className="text-xs font-semibold text-gray-400 uppercase">Tutor Voice</label>
                    <div className="grid grid-cols-2 gap-2">
                        {VOICES.map(voice => (
                            <button
                                key={voice.name}
                                disabled={callState !== CallState.IDLE}
                                onClick={() => setSelectedVoice(voice)}
                                className={`p-3 rounded-lg border text-left transition-all
                                    ${selectedVoice.name === voice.name 
                                        ? 'bg-blue-600/20 border-blue-500 text-blue-100' 
                                        : 'bg-[#131314] border-[#444746] text-gray-400 hover:border-gray-500'
                                    } ${callState !== CallState.IDLE ? 'opacity-50 cursor-not-allowed' : ''}
                                `}
                            >
                                <div className="flex items-center gap-2 mb-1">
                                    <span className="material-icons-round text-sm">
                                        {voice.gender === 'Male' ? 'face' : 'face_3'}
                                    </span>
                                    <span className="font-medium text-sm">{voice.label}</span>
                                </div>
                                <div className="text-xs opacity-70">{voice.description}</div>
                            </button>
                        ))}
                    </div>
                </div>

                {/* Accent Selection */}
                <div className="space-y-3">
                     <label className="text-xs font-semibold text-gray-400 uppercase">Accent Preference</label>
                     <div className="space-y-2">
                        {ACCENTS.map(accent => (
                            <button 
                                key={accent.id}
                                disabled={callState !== CallState.IDLE}
                                onClick={() => setSelectedAccent(accent)}
                                className={`w-full flex items-center justify-between p-3 rounded-lg border transition-all
                                     ${selectedAccent.id === accent.id
                                        ? 'bg-blue-600/20 border-blue-500 text-blue-100' 
                                        : 'bg-[#131314] border-[#444746] text-gray-400 hover:border-gray-500'
                                     } ${callState !== CallState.IDLE ? 'opacity-50 cursor-not-allowed' : ''}
                                `}
                            >
                                <span className="text-sm">{accent.label}</span>
                                {selectedAccent.id === accent.id && <span className="material-icons-round text-sm text-blue-400">check</span>}
                            </button>
                        ))}
                     </div>
                </div>

                {/* Scenario Selection */}
                <div className="space-y-3">
                    <label className="text-xs font-semibold text-gray-400 uppercase">Scenario</label>
                    <div className="space-y-2">
                        {SCENARIOS.map((scenario) => (
                            <button
                                key={scenario.id}
                                disabled={callState !== CallState.IDLE}
                                onClick={() => setSelectedScenario(scenario)}
                                className={`w-full p-3 rounded-lg text-left border transition-all flex items-center gap-3
                                    ${selectedScenario.id === scenario.id 
                                        ? 'bg-[#004a77]/30 border-blue-500/50 text-blue-100' 
                                        : 'bg-[#131314] border-[#444746] text-gray-400 hover:border-gray-500'
                                    } ${callState !== CallState.IDLE ? 'opacity-50 cursor-not-allowed' : ''}
                                `}
                            >
                                <span className="text-xl">{scenario.emoji}</span>
                                <span className="text-sm font-medium">{scenario.title}</span>
                            </button>
                        ))}
                    </div>
                </div>

             </div>
          </div>

          {/* Main Stage */}
          <div className="flex-1 flex flex-col relative z-10 bg-[#1e1e20]">

            {/* Top Bar of Stage */}
            <div className="h-16 border-b border-[#444746] flex items-center justify-between px-6 bg-[#1e1e20]">
                <div className="flex items-center gap-3">
                     <span className="text-xl">{selectedScenario.emoji}</span>
                     <span className="font-medium text-lg">{selectedScenario.title}</span>
                </div>
                <div className="flex items-center gap-4">
                     {callState === CallState.ACTIVE && (
                         <>
                            <button 
                                onClick={() => setShowTranscript(!showTranscript)}
                                className={`p-2 rounded-full hover:bg-[#323235] transition-colors ${showTranscript ? 'text-blue-400' : 'text-gray-400'}`}
                                title="Toggle Transcript"
                            >
                                <span className="material-icons-round">subtitles</span>
                            </button>
                            <span className="px-3 py-1 bg-red-500/10 text-red-400 rounded-full text-xs font-medium border border-red-500/20 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse"></span>
