        correction: string;
        alternative: string;
        explanation: string;
    }>;
}

import { GoogleGenAI, Type } from '@google/genai';
import { AnalysisReport, TranscriptItem } from '../types';

export async function generateAnalysisReport(apiKey: string, transcript: TranscriptItem[]): Promise<AnalysisReport> {
  const ai = new GoogleGenAI({ apiKey });

  // Filter out empty transcripts and format
  const conversationText = transcript
    .filter(t => t.text.trim() !== '')
    .map(t => `${t.speaker === 'user' ? 'Student' : 'Tutor'}: ${t.text}`)
    .join('\n');

  const prompt = `
    Analyze the following English learning conversation. 
    The "Student" is an English learner. 

    1. Evaluate the Student's performance on a scale of 0-100 for:
       - Overall Score
       - Fluency (based on sentence flow and complexity)
       - Vocabulary (range and appropriateness)
       - Grammar (accuracy)
       - Accent Style Match (how well their phrasing matches the target native English style, e.g. using idioms correctly)

    2. Identify 3-5 key errors or areas for improvement.
       - Provide the Original phrase.
       - Provide a Corrected version.
       - Provide an "Alternative" way to say it that sounds more native.
       - Explain the rule or reason.

    3. Provide a brief, encouraging summary (max 2 sentences).

    Conversation:
    ${conversationText}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            fluencyScore: { type: Type.NUMBER },
            vocabularyScore: { type: Type.NUMBER },
            grammarScore: { type: Type.NUMBER },
            accentMatchScore: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            corrections: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  original: { type: Type.STRING },
                  correction: { type: Type.STRING },
                  alternative: { type: Type.STRING },
                  explanation: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from model");
    return JSON.parse(text) as AnalysisReport;
  } catch (error) {
    console.error("Report generation failed", error);
    return {
        score: 0,
        fluencyScore: 0,
        vocabularyScore: 0,
        grammarScore: 0,
        accentMatchScore: 0,
        summary: "Could not generate report due to an error.",
        corrections: []
    };
  }
}

