                                        ${selectedScenario.id === s.id ? 'bg-[#2a2a2c] border-blue-500' : 'bg-[#1e1e20] border-[#333] hover:border-[#555]'}
                                    `}
                                >
                                    <span className="text-xl group-hover:scale-110 transition-transform">{s.emoji}</span>
