                <div className="absolute inset-0 opacity-10 pointer-events-none" 
                     style={{ backgroundImage: 'radial-gradient(#444 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
                </div>

                {callState === CallState.IDLE ? (
                    <div className="text-center z-10 max-w-lg px-6">
                        <div className="w-20 h-20 bg-blue-600 rounded-2xl mx-auto flex items-center justify-center shadow-2xl shadow-blue-600/30 mb-6 transform rotate-3 hover:rotate-6 transition-transform">
                            <span className="material-icons-round text-4xl text-white">record_voice_over</span>
                        </div>
                        <h2 className="text-3xl font-bold mb-3">Ready to practice?</h2>
                        <p className="text-gray-400 mb-8 text-lg">
